import { useDispatch } from "react-redux";
import { changeItemsCount } from "../../store/slices/cartSlice";

const CartItem = ({ name, price, image, color, count, id }) => {
  const dispatch = useDispatch();

  const onChangeItemCount = (count, price) => {
    dispatch(changeItemsCount({ cartItem: { count, id, price } }));
  };

  return (
    <li className="cart-item">
      <img className="cart-item-image" src={image} alt={name} />
      <div className="cart-item-wrapper">
        <div className="cart-item-info">
          <h3>{name}</h3>
          <div className="cart-item-counter">
            <button
              className="cart-count-btn cart-count-btn--dec"
              onClick={() => onChangeItemCount(-1, -price)}
            ></button>
            <span>{count}</span>
            <button
              className="cart-count-btn cart-count-btn--inc"
              onClick={() => onChangeItemCount(1, price)}
            ></button>
          </div>
        </div>
        <div className="cart-item-details">
          <span className="cart-item-price">{price * count} UAH</span>
          <div className="cart-item-details-inner">
            <button
              className="cart-clear-btn"
              onClick={() => onChangeItemCount(-count, -price * count)}
            >
              Delete item
            </button>
            <div
              className="cart-item-color"
              style={{ background: `var(--${color})` }}
            ></div>
          </div>
        </div>
      </div>
    </li>
  );
};

export default CartItem;
